/* -------------------------------------------------------------------------------------------------
 * Status
 *
 * One vocabulary for plan steps, todos and tasks. It maps one to one onto Claude Code TodoWrite
 * (`pending`, `in_progress`, `completed`) and adds the states a real run also hits.
 * -----------------------------------------------------------------------------------------------*/

type TaskStatus =
  | "pending"
  | "in-progress"
  | "done"
  | "blocked"
  | "skipped"
  | "failed"
  | "cancelled"

export interface PlanStep {
  id: string
  /** One line in the imperative: "Wrap RunsHeader in its own Suspense boundary". */
  title: string
  /** Optional second line: why, or where. */
  detail?: string
  /** What went wrong, shown under a failed step in place of `detail`. */
  error?: string
  /** Explicit step status. While running, steps without one are derived from the current step. */
  status?: TaskStatus
}

/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

export type PlanState = "drafting" | "awaiting-approval" | "approved" | "running" | "done" | "rejected"

export interface PlanProps extends Omit<React.ComponentProps<"div">, "title"> {
  /** What the plan achieves. */
  title: React.ReactNode
  /** One or two sentences of context above the steps. */
  description?: React.ReactNode
  steps: PlanStep[]
  state: PlanState
  /** The step the agent is on while running. Defaults to the first step marked `in-progress`. */
  currentStepId?: string
  /** Approve plan. Receives the steps as the user left them. Shows the approval actions. */
  onApprove?: (steps: PlanStep[]) => void
  /** Reject plan, with the note the user typed for the agent. */
  onReject?: (reason?: string) => void
  /** Saving an edit. Without it, Edit plan is hidden. */
  onStepsChange?: (steps: PlanStep[]) => void
  /** Why the plan was rejected, shown in the rejected state. */
  rejectedReason?: React.ReactNode
  /** Edit mode, controlled. Use with `onEditingChange`. */
  editing?: boolean
  defaultEditing?: boolean
  onEditingChange?: (editing: boolean) => void
  /** Retry a failed step. Shows Retry on that step's row, in place. Receives the step id. */
  onRetryStep?: (stepId: string) => void
  /** Let the header fold the steps away, for a plan that has moved up the transcript. */
  collapsible?: boolean
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
}

/** Resolves every step's status from the plan state and the current step. */
function resolveStatuses(steps: PlanStep[], state: PlanState, currentStepId?: string) {
  if (state === "done") return steps.map((s) => s.status ?? "done")
  if (state !== "running") return steps.map((s) => s.status ?? "pending")
  let current = currentStepId ? steps.findIndex((s) => s.id === currentStepId) : -1
  if (current === -1) current = steps.findIndex((s) => s.status === "in-progress")
  return steps.map((s, i): TaskStatus => {
    if (s.status) return s.status
    if (current === -1) return "pending"
    if (i < current) return "done"
    if (i === current) return "in-progress"
    return "pending"
  })
}

/* -------------------------------------------------------------------------------------------------
 * Helpers
 * -----------------------------------------------------------------------------------------------*/

const STATE_TEXT: Record<PlanState, string> = {
  drafting: "Drafting",
  "awaiting-approval": "Awaiting approval",
  approved: "Approved",
  running: "Running",
  done: "Done",
  rejected: "Rejected",
}

interface IconProps extends SVGAttributes<SVGSVGElement> {
  /** Width and height. Number means px. Default 24. */
  size?: number | string
  /** Stroke width in viewBox units (24 grid). Default 1.5. */
  strokeWidth?: number | string
  /** Keep the rendered stroke at `strokeWidth` px at any size. */
  absoluteStrokeWidth?: boolean
  /** Stroke color. Default currentColor. */
  color?: string
  /** Accessible name. Renders <title> and sets role="img"; without it the icon is aria-hidden. */
  title?: string
}

type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>

/** Shape elements an icon may contain. */
type IconElement = "path" | "circle" | "rect" | "ellipse" | "line" | "polyline" | "polygon"

/** An icon's drawing: a flat list of [element, attributes] pairs, lucide compatible. */
type IconNode = ReadonlyArray<readonly [IconElement, Readonly<Record<string, string>>]>

const toPascal = (name: string): string =>
  name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

/**
 * Builds a React icon component from an icon node.
 * `name` is the kebab-case icon name, used for the class `chatcn-icon-<name>` and displayName.
 */
function createIcon(name: string, iconNode: IconNode): Icon {
  // biome-ignore lint/correctness/noComponentHookFactories: runs once per icon at module load
  const Component = forwardRef<SVGSVGElement, IconProps>(function ChatcnIcon(
    {
      size = 24,
      strokeWidth = 1.5,
      absoluteStrokeWidth = false,
      color = "currentColor",
      title,
      className,
      children,
      ...rest
    },
    ref,
  ) {
    const stroke = absoluteStrokeWidth
      ? (Number(strokeWidth) * 24) / Number.parseFloat(String(size))
      : strokeWidth
    const labelled = Boolean(title || rest["aria-label"] || rest["aria-labelledby"])
    return createElement(
      "svg",
      {
        ref,
        xmlns: "http://www.w3.org/2000/svg",
        width: size,
        height: size,
        viewBox: "0 0 24 24",
        fill: "none",
        stroke: color,
        strokeWidth: stroke,
        strokeLinecap: "round",
        strokeLinejoin: "round",
        "data-slot": "icon",
        className: className
          ? `chatcn-icon chatcn-icon-${name} ${className}`
          : `chatcn-icon chatcn-icon-${name}`,
        ...(labelled ? { role: "img" } : { "aria-hidden": true }),
        ...rest,
      },
      title ? createElement("title", null, title) : null,
      ...iconNode.map(([tag, attrs], i) => createElement(tag, { key: i, ...attrs })),
      children,
    )
  })
  Component.displayName = `${toPascal(name)}Icon`
  return Component
}

