function PlanEditor({
  initial,
  onSave,
  onCancel,
}: {
  initial: PlanStep[]
  onSave: (steps: PlanStep[]) => void
  onCancel: () => void
}) {
  const [draft, setDraft] = React.useState(() =>
    initial.length > 0 ? initial : [{ id: newStepId(), title: "" }],
  )
  const [focusId, setFocusId] = React.useState<string | null>(null)
  const ids = draft.map((s) => s.id)
  const reorder = useChatcnPlanReorder({
    ids,
    noun: "step",
    label: (id) => {
      const i = draft.findIndex((s) => s.id === id)
      return `${i + 1}${draft[i]?.title ? `, ${draft[i]?.title}` : ""}`
    },
    onMove: (from, to) => setDraft((d) => moveItem(d, from, to)),
  })

  const save = () => {
    const cleaned = draft
      .map((s) => ({ ...s, title: s.title.trim() }))
      .filter((s) => s.title.length > 0)
    onSave(cleaned)
  }

  const insertAfter = (index: number) => {
    const step = { id: newStepId(), title: "" }
    setDraft((d) => [...d.slice(0, index + 1), step, ...d.slice(index + 1)])
    setFocusId(step.id)
  }

  return (
    <div data-slot="plan-editor" className="flex flex-col">
      <ol aria-label="Plan steps" className="relative flex flex-col gap-0.5 px-1.5">
        {draft.map((step, index) => (
          <PlanEditRow
            key={step.id}
            step={step}
            index={index}
            count={draft.length}
            autoFocus={focusId === step.id}
            dragging={reorder.draggingId === step.id}
            itemProps={reorder.getItemProps(step.id)}
            handleProps={reorder.getHandleProps(step.id)}
            onChange={(title) =>
              setDraft((d) => d.map((s) => (s.id === step.id ? { ...s, title } : s)))
            }
            onEnter={() => insertAfter(index)}
            onRemove={(focusPrevious) => {
              const previous = draft[index - 1] ?? draft[index + 1]
              setDraft((d) => d.filter((s) => s.id !== step.id))
              if (focusPrevious && previous) setFocusId(previous.id)
            }}
            onMove={(delta) => reorder.moveBy(step.id, index + delta)}
            onCancel={onCancel}
            onSave={save}
          />
        ))}
      </ol>
      <div className="px-1.5 pt-0.5">
        <button
          type="button"
          onClick={() => insertAfter(draft.length - 1)}
          className={cn(
            "chatcn-focus rounded-(--chatcn-radius-sm) text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) flex h-8 w-full items-center gap-2 px-1.5",
            "hover:bg-(color:--chatcn-fill-hover) hover:text-(color:--chatcn-fg) ease-(--chatcn-ease-standard) transition-colors duration-150",
            "pointer-coarse:h-11",
          )}
        >
          <span className="grid w-5 place-items-center">
            <PlusIcon aria-hidden="true" className="size-4" />
          </span>
          Add step
        </button>
      </div>
      <span aria-live="polite" className="sr-only">
        {reorder.announcement}
      </span>
      <div className="border-(color:--chatcn-border)/70 mt-2 flex items-center justify-end gap-1.5 border-t p-1.5 ps-4">
        <p className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) me-auto hidden min-w-0 truncate @[34rem]/plan:block">
          Enter adds a step. Drag or use the arrow keys on a handle to reorder.
        </p>
        <Button size="sm" onClick={onCancel}>
          Cancel
        </Button>
        <Button size="sm" variant="solid" onClick={save}>
          Save plan
        </Button>
      </div>
    </div>
  )
}

