/**
 * The agent's proposed plan, from first streamed step to the last one done. Drafting streams steps
 * in, awaiting approval asks before anything runs, editing makes every step a line you can type
 * in, drag or move with the keyboard, and running highlights the step the agent is on.
 */
export function Plan({
  title,
  description,
  steps,
  state,
  currentStepId,
  onApprove,
  onReject,
  onStepsChange,
  onRetryStep,
  rejectedReason,
  editing: editingProp,
  defaultEditing = false,
  onEditingChange,
  collapsible = false,
  open: openProp,
  defaultOpen = true,
  onOpenChange,
  className,
  ...props
}: PlanProps) {
  const [editingState, setEditingState] = React.useState(defaultEditing)
  const canEdit = onStepsChange !== undefined && state === "awaiting-approval"
  const editing = canEdit && (editingProp ?? editingState)
  const setEditing = (next: boolean) => {
    if (editingProp === undefined) setEditingState(next)
    onEditingChange?.(next)
  }

  const [openState, setOpenState] = React.useState(defaultOpen)
  const open = collapsible ? (openProp ?? openState) : true
  const setOpen = (next: boolean) => {
    if (openProp === undefined) setOpenState(next)
    onOpenChange?.(next)
  }

  // Steps present at mount appear at once; steps streamed in later rise in.
  const [initialIds] = React.useState(() => new Set(steps.map((s) => s.id)))
  const statuses = resolveStatuses(steps, state, currentStepId)
  const numbered = state === "drafting" || state === "awaiting-approval" || state === "rejected"
  const currentIndex = statuses.indexOf("in-progress")
  const doneCount = statuses.filter((s) => s === "done").length

  let stateLabel: React.ReactNode = editing ? "Editing" : STATE_TEXT[state]
  // One running signal at a time: the body's "Thinking" shimmer before the first step lands,
  // then the caret on the step that is streaming. The label itself holds still.
  if (state === "drafting") stateLabel = "Drafting"
  else if (state === "running" && currentIndex !== -1)
    stateLabel = `Step ${currentIndex + 1} of ${steps.length}`
  else if (state === "running" && statuses.includes("failed")) stateLabel = "Stopped on a failure"
  else if (state === "running") stateLabel = `${doneCount} of ${steps.length} done`
  else if (state === "done") stateLabel = `${doneCount} of ${steps.length} done`

  const header = (
    <>
      <ListChecksIcon aria-hidden="true" className="text-(color:--chatcn-fg-subtle) size-4 shrink-0" />
      <span className="text-(color:--chatcn-fg) min-w-0 flex-1 truncate font-medium">{title}</span>
      <span
        aria-live="polite"
        className={cn(
          "text-[0.75rem]/[1rem] shrink-0 tabular-nums",
          state === "awaiting-approval" ? "text-(color:--chatcn-fg)" : "text-(color:--chatcn-fg-subtle)",
        )}
      >
        {stateLabel}
      </span>
      {collapsible ? (
        <ChevronDownIcon
          aria-hidden="true"
          className={cn(
            "text-(color:--chatcn-fg-subtle) ease-(--chatcn-ease-out) size-4 shrink-0 transition-transform duration-200 motion-reduce:transition-none",
            open && "rotate-180",
          )}
        />
      ) : null}
    </>
  )

  const headerClass = "flex h-11 w-full min-w-0 items-center gap-3 px-4 text-start"

  return (
    // biome-ignore lint/a11y/useSemanticElements: keeps the div props and ref the API exposes
    <div
      role="region"
      aria-label={typeof title === "string" ? `Plan: ${title}` : "Plan"}
      data-slot="plan"
      data-plan-state={state}
      data-editing={editing ? "" : undefined}
      className={cn(
        "text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) rounded-(--chatcn-radius-lg) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-sm) @container/plan flex min-w-0 flex-col overflow-hidden",
        className,
      )}
      {...props}
    >
      <Collapsible.Root open={open} onOpenChange={setOpen} disabled={!collapsible} render={<div />}>
        {collapsible ? (
          <Collapsible.Trigger
            className={cn(
              headerClass,
              "hover:bg-(color:--chatcn-alpha-100) ease-(--chatcn-ease-standard) transition-colors duration-150 outline-none select-none",
              "focus-visible:outline-(color:--chatcn-accent) focus-visible:outline-2 focus-visible:-outline-offset-2",
            )}
          >
            {header}
          </Collapsible.Trigger>
        ) : (
          <div className={headerClass}>{header}</div>
        )}

        <Collapsible.Panel
          className={cn(
            "h-(--collapsible-panel-height) overflow-hidden",
            "ease-(--chatcn-ease-out) transition-[height,opacity] duration-200 motion-reduce:transition-none",
            "data-[ending-style]:h-0 data-[ending-style]:opacity-0 data-[ending-style]:duration-150",
            "data-[starting-style]:h-0 data-[starting-style]:opacity-0",
          )}
        >
          {description ? (
            <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) -mt-1 px-4 pb-2 text-pretty">
              {description}
            </p>
          ) : null}

          {editing ? (
            <PlanEditor
              initial={steps}
              onCancel={() => setEditing(false)}
              onSave={(next) => {
                onStepsChange?.(next)
                setEditing(false)
              }}
            />
          ) : (
            <>
              {steps.length === 0 ? (
                <p className="text-(color:--chatcn-fg-subtle) text-[0.8125rem]/[1.25rem] px-4 pb-3">
                  {state === "drafting" ? (
                    <ShimmerText>Thinking through the steps</ShimmerText>
                  ) : (
                    "This plan has no steps."
                  )}
                </p>
              ) : (
                <ol
                  aria-label="Plan steps"
                  className={cn(
                    "flex flex-col gap-0.5 px-1.5",
                    state === "awaiting-approval" || state === "rejected" || state === "approved"
                      ? "pb-2"
                      : "pb-1.5",
                  )}
                >
                  {steps.map((step, index) => (
                    <PlanStepRow
                      key={step.id}
                      step={step}
                      index={index}
                      status={statuses[index] ?? "pending"}
                      numbered={numbered}
                      streaming={state === "drafting" && index === steps.length - 1}
                      animate={!initialIds.has(step.id)}
                      onRetry={onRetryStep ? () => onRetryStep(step.id) : undefined}
                    />
                  ))}
                </ol>
              )}

              {state === "awaiting-approval" ? (
                <PlanActions
                  canEdit={canEdit}
                  onApprove={onApprove ? () => onApprove(steps) : undefined}
                  onReject={onReject}
                  onEdit={() => setEditing(true)}
                />
              ) : null}

              {state === "approved" ? (
                <p className="border-(color:--chatcn-border)/70 text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) flex h-10 items-center gap-2 border-t px-4">
                  <CheckIcon aria-hidden="true" className="size-4 shrink-0" />
                  Approved. The agent is starting.
                </p>
              ) : null}

              {state === "rejected" ? (
                <p className="border-(color:--chatcn-border)/70 text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) flex min-h-10 items-center gap-2 border-t px-4 py-2">
                  <BanIcon aria-hidden="true" className="size-4 shrink-0" />
                  <span className="min-w-0 text-pretty">
                    {rejectedReason ? <>Rejected: {rejectedReason}</> : "Rejected. Nothing ran."}
                  </span>
                </p>
              ) : null}
            </>
          )}
        </Collapsible.Panel>
      </Collapsible.Root>
    </div>
  )
}

